Section M2.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x24 x25 x26 x27 : word).        (* [comment removed for export] *)
  Variables (m : fmem) (WK DT mtl iS nbS tl : Z) (ws rank : list Z) (jk js jt jf : list byte) (rsw0 : list word).
  Variables (rs : list Z) (rs2 : list Z) (syms : list (option Z)) (cells : list (option deltX1)).
  Variable POST : machine_state -> Prop.
  Notation SP := (bv_unsigned sp).
  Notation HW := (WK + 1236).
  Notation SY := (WK + 980).
  Notation RS := (WK + 52).
  Notation NC := (Z.to_nat (2^(mtl + 1))).
  Hypothesis HMTL : 1 <= mtl <= 12.
  Hypothesis HTL : 1 <= tl <= mtl + 1.
  Hypothesis HTL12 : tl <= 12.
  Hypothesis HIS : 1 <= iS <= 129.
  Hypothesis WFW : WF ws rank nbS tl.
  Hypothesis LJK : zlen jk = 256 - nbS.
  Hypothesis LJS : length js = 256%nat.
  Hypothesis LJT : length jt = (2 * NC)%nat.
  Hypothesis LJF : length jf = 48%nat.
  Hypothesis LRW : length rsw0 = 13%nat.
  Hypothesis RSL : rank_start_loop (Z.to_nat (tl + 1)) 0 0 rank (repeat 0 13) = Ok rs.
  Hypothesis SOL : sort_loop (Z.to_nat nbS) 0 ws rs (repeat None 256) = Ok (rs2, syms).
  Hypothesis FWL : fill_weights (Z.to_nat tl) 1 tl rank syms (repeat None NC) (Znth 0 rank) 0 = Ok cells.
  Hypothesis HWK : 0 < WK /\ WK + 1492 <= 2^47.
  Hypothesis HDT : 0 < DT /\ DT + 4 + 2 * 2^(mtl + 1) <= 2^47.
  Hypothesis DJW : DT + 4 + 2 * 2^(mtl + 1) <= WK \/ WK + 1492 <= DT.
  Hypothesis HSP : WK + 1492 <= SP /\ DT + 4 + 2 * 2^(mtl + 1) <= SP /\ SP + 176 <= 2^47.
  Hypothesis D4 : u8arr psegs m DT (le4 (Z_to_bv 64 (mtl * 16777217))).
  Hypothesis DTC : u8arr psegs m (DT + 4) jt.
  Hypothesis RKA : u32arr psegs m WK (map (Z_to_bv 64) rank).
  Hypothesis RSA : u32arr psegs m RS rsw0.
  Hypothesis SYA : u8arr psegs m SY js.
  Hypothesis HWA : u8arr psegs m HW (map (Z_to_bv 8) ws ++ jk).
  Hypothesis FRS : rw_cells psegs m (SP + 16) [CB 48 jf].
  Hypothesis MI : mem_inv psegs m.

  Notation WALL := [(DT, DT + 4 + 2 * 2^(mtl + 1)); (WK, WK + 1492); (SP + 16, SP + 64)].

  Notation KT := (forall m3 (z1 z5 z6 z7 z10 z11 z12 z13 z14 z15 z16 z17 z18 z19 z20 z21 z22 z23 z24 z25 z26 z27 z28 z29 z30
                             z31 : word),
       u8arr psegs m3 DT [Z_to_bv 8 mtl; Z_to_bv 8 0; Z_to_bv 8 tl; Z_to_bv 8 mtl] ->
       u8arr psegs m3 (DT + 4) (ox1 jt cells) ->
       rw_cells psegs m3 (SP + 16) (C8 (Z_to_bv 64 iS) :: x1_slots DT) ->
       munch WALL m m3 -> wmono psegs m m3 -> mem_inv psegs m3 ->
       evt psegs POST (MS (mkR z1 sp gp tp z5 z6 z7 (Z_to_bv 64 WK) (Z_to_bv 64 DT) z10 z11 z12 z13 z14 z15 z16 z17 z18 z19 z20
                               z21 z22 z23 z24 z25 z26 z27 z28 z29 z30 z31)
                          F (Z_to_bv 64 0x139ec) fc None m3 (seg_rom psegs))).

